ProgressCb = Callable[[dict[str, Any]], None]
CueCb = Callable[[dict[str, Any]], None]
_log = logging.getLogger("transub_engine.asr.qwen3_asr")

def qwen3_asr_transcribe(
    *,
    media_path: str,
    language: str = "auto",
    asr_model: str = "qwen3-asr-0.6b",
    device: str = "auto",
    timing_align_model: str | None = None,
    vad_model: str | None = None,
    vad_options: dict[str, Any] | None = None,
    qwen_batch_mode: str | None = "auto",
    perf_profile: str | None = None,
    job_gpu_free_mib: int | None = None,
    job_gpu_total_mib: int | None = None,
    vad_media_path: str | None = None,
    timing_media_path: str | None = None,
    singing_karaoke: bool | None = None,
    on_progress: ProgressCb | None = None,
    on_cue: CueCb | None = None,
    should_cancel: Callable[[], bool] | None = None,
) -> list[dict[str, Any]]:
    from ..runtime_extras import ensure_extras_for_models, ensure_numpy_numba_compatible

    # Emit BEFORE torch import — first CUDA load can take minutes with no other events.
    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 2,
                "detail": f"准备加载 {asr_model}（导入 Torch）…",
            }
        )

    # Prefer fixing numpy while native DLLs are still unlocked. Serve usually
    # does this before preload; keep a job-time pass for older engine processes.
    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 2,
                "detail": "检查 NumPy / Numba 兼容性…",
            }
        )
    fix_early = ensure_numpy_numba_compatible(on_progress=on_progress)
    if not fix_early.get("ok"):
        raise RuntimeError(
            "Numba needs NumPy <2.5; "
            f"auto-fix failed: {fix_early.get('message') or 'pip error'}"
        )

    from ..device import (
        format_torch_cuda_load_failure,
        is_torch_fully_imported,
        is_torch_reimport_poisoned,
        torch_reimport_poison_message,
    )

    if is_torch_reimport_poisoned():
        raise RuntimeError(torch_reimport_poison_message())

    # Serve may have preloaded torch (torch\\lib before nvidia inject). Skip costly probe.
    if is_torch_fully_imported():
        if on_progress:
            on_progress(
                {
                    "stage": "model",
                    "percent": 5,
                    "detail": "Torch 已就绪 · 检查运行依赖…",
                }
            )
    elif sys.platform == "win32":
        if on_progress:
            on_progress(
                {
                    "stage": "model",
                    "percent": 3,
                    "detail": "检测 Torch/CUDA（子进程）…",
                }
            )
        if not _probe_torch_cuda_import(timeout_sec=60.0):
            if on_progress:
                on_progress(
                    {
                        "stage": "model",
                        "percent": 4,
                        "detail": "子进程导入失败 · 尝试本进程预加载 Torch…",
                    }
                )
            try:
                from ..runtime_gpu import preload_torch_cuda_dlls

                pre = preload_torch_cuda_dlls()
                if not pre.get("ok"):
                    raise RuntimeError(
                        format_torch_cuda_load_failure(pre.get("message") or "")
                    )
            except RuntimeError:
                raise
            except Exception as err:
                raise RuntimeError(format_torch_cuda_load_failure(err)) from err

    # Windows: load torch before ensure_extras can further poison cuBLAS.
    try:
        _import_torch()
    except Exception as err:
        _log.warning("Qwen3-ASR: early torch import failed: %s", err)
        raise

    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 5,
                "detail": "Torch 已就绪 · 检查运行依赖…",
            }
        )

    use_aligner = wants_forced_aligner(timing_align_model)
    ensure_ids = [asr_model]
    if use_aligner:
        ensure_ids.append(_ALIGNER_ID)
    ensure_extras_for_models(
        ensure_ids,
        force=False,
        on_progress=on_progress,
    )
    # Repair numpy floated by unconstrained pip during extras install.
    fix = ensure_numpy_numba_compatible(on_progress=on_progress)
    if not fix.get("ok"):
        raise RuntimeError(
            "Numba needs NumPy <2.5; "
            f"auto-fix failed: {fix.get('message') or 'pip error'}"
        )
    if not is_model_installed(asr_model):
        asr_dir = model_local_path(asr_model)
        missing: list[str] = []
        try:
            from .qwen3_hf_convert import missing_safetensors_shards

            missing = missing_safetensors_shards(asr_dir)
        except Exception:
            missing = []
        extra = (
            f" 权重分片不完整，缺少 {', '.join(missing[:6])}。"
            "请重新下载该模型（已下好的分片会续传）。"
            if missing
            else ""
        )
        raise RuntimeError(
            f"ASR model not installed: {asr_model}.{extra} "
            f"Download {asr_model} (or qwen3-asr-0.6b) first."
        )
    asr_dir = model_local_path(asr_model)
    aligner_dir: Path | None = None
    if use_aligner:
        try:
            if is_model_installed(_ALIGNER_ID):
                aligner_dir = model_local_path(_ALIGNER_ID)
            else:
                _log.warning(
                    "ForcedAligner requested but %s not installed; "
                    "falling back to VAD/window timing",
                    _ALIGNER_ID,
                )
                use_aligner = False
        except Exception:
            aligner_dir = None
            use_aligner = False

    if on_progress:
        mode = " + ForcedAligner…" if use_aligner and aligner_dir else "（VAD 帧时间戳）…"
        on_progress(
            {
                "stage": "model",
                "percent": 8,
                "detail": f"加载 Qwen3-ASR{mode}",
            }
        )
    # Resolve batch before loading weights — post-load mem_get_info under-estimates headroom.
    island_batch_n = resolve_island_batch_size(
        asr_model,
        batch_mode=qwen_batch_mode,
        device=device,
        perf_profile=perf_profile,
        job_gpu_free_mib=job_gpu_free_mib,
        job_gpu_total_mib=job_gpu_total_mib,
    )
    batch_label = _effective_batch_mode(qwen_batch_mode, perf_profile)
    vram_free, vram_total = _resolve_vram_mib(
        job_gpu_free_mib=job_gpu_free_mib,
        job_gpu_total_mib=job_gpu_total_mib,
    )
    _log.info(
        "Qwen3 island batch plan: model=%s mode=%s batch=%d device=%s vram_free=%s vram_total=%s",
        asr_model,
        batch_label,
        island_batch_n,
        device,
        vram_free,
        vram_total,
    )
    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 10,
                "detail": "加载 Qwen3-ASR 权重到设备（首次可能较久）…",
            }
        )
    model = _get_asr_model(asr_dir, aligner_dir if use_aligner else None, device)
    lang = _map_language(language)
    duration_s = _probe_duration_s(media_path)
    if duration_s <= 0:
        raise RuntimeError(
            f"无法读取媒体时长（{media_path}），Qwen3-ASR 不能安全开窗。"
            "请确认 ffmpeg/ffprobe 可用后重试。"
        )

    cleaned: list[dict[str, Any]] = []
    if use_aligner and aligner_dir is not None:
        # ForcedAligner always rides VAD islands (TEN default / FireRed when selected).
        # Legacy fixed 90s windows drop soft-AV dialogue — only used if island collect fails.
        aligner_island = _aligner_island_backend(vad_model, timing_align_model)
        if aligner_island == "firered":
            ensure_extras_for_models(
                ["firered-vad"],
                force=False,
                on_progress=on_progress,
            )
        vad_cues = _qwen_island_vad_transcribe(
            media_path=media_path,
            model=model,
            lang=lang,
            duration_s=duration_s,
            vad_backend=aligner_island,
            device=device,
            asr_model=asr_model,
            asr_dir=asr_dir,
            aligner_dir=aligner_dir,
            qwen_batch_mode=qwen_batch_mode,
            perf_profile=perf_profile,
            job_gpu_free_mib=job_gpu_free_mib,
            job_gpu_total_mib=job_gpu_total_mib,
            island_batch_n=island_batch_n,
            want_ts=True,
            vad_options=vad_options,
            vad_media_path=vad_media_path,
            timing_media_path=timing_media_path,
            singing_karaoke=singing_karaoke,
            on_progress=on_progress,
            on_cue=on_cue,
            should_cancel=should_cancel,
        )
        if vad_cues is not None:
            cleaned = vad_cues
        else:
            cleaned = _qwen_windowed_transcribe(
                media_path=media_path,
                model=model,
                lang=lang,
                duration_s=duration_s,
                want_ts=True,
                on_progress=on_progress,
                on_cue=on_cue,
                should_cancel=should_cancel,
            )
    else:
        # Default + aligner-missing fallback: TEN/FireRed frames; empty timingAlign → windows.
        island_backend = _island_vad_backend(
            None if wants_forced_aligner(timing_align_model) else timing_align_model
        )
        if island_backend:
            if island_backend == "firered":
                ensure_extras_for_models(
                    ["firered-vad"],
                    force=False,
                    on_progress=on_progress,
                )
            vad_cues = _qwen_island_vad_transcribe(
                media_path=media_path,
                model=model,
                lang=lang,
                duration_s=duration_s,
                vad_backend=island_backend,
                device=device,
                asr_model=asr_model,
                asr_dir=asr_dir,
                aligner_dir=aligner_dir,
                qwen_batch_mode=qwen_batch_mode,
                perf_profile=perf_profile,
                job_gpu_free_mib=job_gpu_free_mib,
                job_gpu_total_mib=job_gpu_total_mib,
                island_batch_n=island_batch_n,
                want_ts=False,
                vad_options=vad_options,
                vad_media_path=vad_media_path,
                timing_media_path=timing_media_path,
                singing_karaoke=singing_karaoke,
                on_progress=on_progress,
                on_cue=on_cue,
                should_cancel=should_cancel,
            )
            if vad_cues is not None:
                cleaned = vad_cues
            else:
                cleaned = _qwen_windowed_transcribe(
                    media_path=media_path,
                    model=model,
                    lang=lang,
                    duration_s=duration_s,
                    want_ts=False,
                    on_progress=on_progress,
                    on_cue=on_cue,
                    should_cancel=should_cancel,
                )
        else:
            cleaned = _qwen_windowed_transcribe(
                media_path=media_path,
                model=model,
                lang=lang,
                duration_s=duration_s,
                want_ts=False,
                on_progress=on_progress,
                on_cue=on_cue,
                should_cancel=should_cancel,
            )

    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 96,
                "detail": f"{len(cleaned)} 条（Qwen3-ASR）",
                "processedSec": duration_s,
                "mediaDurationSec": duration_s,
            }
        )
    return cleaned


